-- 0054: تعميق الحوكمة (المرحلة 2): الإطار الإداري — حدود الاعتماد، اللجان، التقويم السنوي، سجل المخاطر.
-- جدول واحد gov_frame بأنواع (intro/auth/comm/cal/risk) والتفاصيل في data؛ البذرة مرة واحدة (seed_marks) فلا تُمس تعديلات المسؤول.
create table if not exists public.gov_frame (
  code text primary key,
  kind text not null check (kind in ('intro','auth','comm','cal','risk')),
  title text not null,
  grp text not null default '',
  sort int not null default 0,
  data jsonb not null default '{}'::jsonb,
  active boolean not null default true,
  updated_at timestamptz not null default now());
create index if not exists gov_frame_kind on public.gov_frame(kind, sort);
alter table public.gov_frame enable row level security;
drop policy if exists p_read on public.gov_frame; create policy p_read on public.gov_frame for select using (public.can_read());
drop policy if exists p_admin on public.gov_frame; create policy p_admin on public.gov_frame for all using (public.is_admin()) with check (public.is_admin());
grant select, insert, update, delete on public.gov_frame to authenticated;

do $$ begin
  if not exists (select 1 from public.seed_marks where key = 'gov_frame_v1') then
  end if;
end $$;
