    insert into public.gov_frame(code,kind,title,grp,sort,data) values ('I-AUTH','intro','حدود الاعتماد','',1,'{"text": "من يقترح ومن يراجع ومن يعتمد كل قرار مؤثر في الإدارة، وحدوده المالية والزمنية. الحدود المالية مقترحة وتُطابَق مع لائحة الصلاحيات المعتمدة في التجمع ونظام المنافسات والمشتريات الحكومية قبل اعتمادها.", "points": ["لا يعتمد أحد ما اقترحه بنفسه؛ المقترِح والمعتمِد شخصان مختلفان دائماً.", "لا يُجزَّأ عمل أو شراء لينزل تحت حد اعتماد أدنى؛ العبرة بقيمة الاحتياج كاملاً.", "التفويض عند الغياب مكتوب ومحدد المدة، ولا يتجاوز صلاحية المفوِّض، ولا يُفوَّض مرة ثانية.", "كل اعتماد يُسجَّل في المنصة على العمل أو المشروع نفسه، ولا يُعتد بالاعتماد الشفهي إلا في الطوارئ ويُوثق خلال يوم عمل.", "عند تعارض هذا الجدول مع لائحة معتمدة في التجمع تُطبَّق اللائحة ويُحدَّث الجدول."]}'::jsonb) on conflict (code) do nothing;
    insert into public.gov_frame(code,kind,title,grp,sort,data) values ('I-COMM','intro','اللجان والاجتماعات','',2,'{"text": "اللجان الدائمة والمؤقتة في الإدارة: لماذا وُجدت، ومن يرأسها، ومتى تجتمع، وما الذي يخرج منها. كل لجنة تُدار بمحضر في المنصة (P-12) وتُتابَع قراراتها كمهام حتى إغلاقها.", "points": ["لا تنعقد اللجنة إلا بنصابها، ويُذكر الحضور والغياب في المحضر.", "كل قرار له مسؤول وموعد، ويُعرض المتأخر في الاجتماع التالي.", "يُفصح العضو عن أي تعارض مصالح قبل البند ويخرج من التصويت عليه."]}'::jsonb) on conflict (code) do nothing;
    insert into public.gov_frame(code,kind,title,grp,sort,data) values ('I-CAL','intro','التقويم السنوي','',3,'{"text": "الأعمال الدورية التي لا يجوز أن تفوت: اختبارات الأنظمة الحرجة، التمارين، مراجعات الخطط، الميزانية والتقارير. المرجع الأساسي معايير سباهي للمنشآت الصحية (فصل إدارة المرافق والسلامة) مع أكواد NFPA وكود البناء السعودي، والتكرار المذكور هو الحد الأدنى.", "points": ["النشاط الذي له نموذج في المنصة يُجدول خطةً دورية فيظهر أمر العمل تلقائياً قبل موعده.", "ما لم يُنفذ في شهره يُعرض في اجتماع الإدارة الشهري (C-06) بسببه."]}'::jsonb) on conflict (code) do nothing;
    insert into public.gov_frame(code,kind,title,grp,sort,data) values ('I-RISK','intro','سجل المخاطر','',4,'{"text": "المخاطر الرئيسية على خدمات الإدارة ومنشآت التجمع، بتقييم الاحتمال والأثر (1–5)، والضوابط القائمة، وخطة المعالجة ومالكها. يراجعه مدير الإدارة ربع سنوياً، ولجنة إدارة المرافق والسلامة (C-01) سنوياً ضمن تحليل قابلية التأثر بالمخاطر.", "points": ["الدرجة = الاحتمال × الأثر: 1–4 منخفض، 5–9 متوسط، 10–14 مرتفع، 15–25 حرج.", "الخطر الحرج يُرفع للإدارة التنفيذية بخطة معالجة وموعد.", "يُضاف خطر جديد بعد أي حادث كبير أو تغير في الخدمات أو المباني."]}'::jsonb) on conflict (code) do nothing;
    insert into public.gov_frame(code,kind,title,grp,sort,data) values ('A-01','auth','تحويل احتياج إلى مشروع','المشاريع والعقود',5,'{"propose": ["FAC", "MNT"], "review": ["PRJ"], "approve": ["DIR"], "limit": "عند تحقق أحد معايير R-01", "ref": "R-01 · G-02"}'::jsonb) on conflict (code) do nothing;
