    insert into public.gov_frame(code,kind,title,grp,sort,data) values ('C-01','comm','لجنة إدارة المرافق والسلامة','دائمة',34,'{"purpose": "الإشراف على خطط إدارة المرافق والسلامة في منشآت التجمع ومتابعة أدائها، وتمثل مرجع الإدارة أمام متطلبات سباهي في هذا الفصل.", "chair": "DIR", "secretary": "SAF", "members": ["PRJ", "FAC", "MNT", "BME", "MED", "GEN", "IT", "SAF", "ممثل مكافحة العدوى", "ممثل التمريض", "ممثل الجودة وسلامة المرضى"], "freq": "شهرياً، واستثنائياً بعد أي حدث كبير", "quorum": "الرئيس أو نائبه + نصف الأعضاء", "duties": ["مراجعة مؤشرات الخطط السبع ونتائج الجولات (F-02)", "مراجعة الحوادث والتعطيلات والإيقافات المخططة (H-01، H-03، M-02)", "اعتماد تحليل قابلية التأثر بالمخاطر السنوي وسجل المخاطر", "اعتماد التقييم السنوي لخطط إدارة المرافق وخطة العام التالي (F-04)", "متابعة جاهزية الاعتماد ونتائج زيارات سباهي والدفاع المدني"], "outputs": ["محضر شهري بالقرارات والمسؤولين", "تقرير ربع سنوي إلى لجنة الجودة وسلامة المرضى في التجمع", "التقييم السنوي للخطط"], "reports_to": "لجنة الجودة وسلامة المرضى / الإدارة التنفيذية", "procs": "F-04 · F-02 · H-03"}'::jsonb) on conflict (code) do nothing;
    insert into public.gov_frame(code,kind,title,grp,sort,data) values ('C-02','comm','لجنة الاستلام الفنية','مؤقتة لكل مشروع',35,'{"purpose": "استلام أعمال المشاريع ابتدائياً ونهائياً والتحقق من مطابقتها وجاهزيتها للتشغيل الآمن.", "chair": "PRJ", "secretary": "مهندس المشروع", "members": ["FAC", "MNT", "SAF", "IT (حسب النطاق)", "BME (حسب النطاق)", "ممثل المنشأة"], "freq": "عند إشعار المقاول بالجاهزية، وقبل نهاية الضمان", "quorum": "الرئيس + الأمن والسلامة + الصيانة", "duties": ["الفحص والتشغيل الفعلي لكل نظام", "تسجيل الملاحظات بالصور ومهل إنهائها", "التحقق من ملف التسليم (As-built، ضمانات، كتيبات)", "التوصية بالاستلام أو رفضه"], "outputs": ["محضر الاستلام الابتدائي أو النهائي", "قائمة الملاحظات بمهلها"], "reports_to": "مدير الإدارة", "procs": "G-04 · P-13 · P-14"}'::jsonb) on conflict (code) do nothing;
